arguments.command:
python3 -I -c "
import json,re
def strict_acc(fn):
    acc=0
    rows=[json.loads(l) for l in open(fn)]
    for r in rows:
        s=r['output'][-300:]
        sols=re.findall('#### (\-?[0-9\.\,]+)', s)
        if sols and sols[-1].replace(',','').replace('\$','')==str(r['gts']):
            acc+=1
    return acc/len(rows)
for step in [0,10,20,30,40,50,60]:
    print(step, strict_acc(f'results/run60/val_generations/{step}.jsonl'))
"

